#![allow(dead_code)]
//! Project marks, extruded. GENERATED by scripts/marks.py -- do not
//! edit. Unlike the tool logos these are authored at their final
//! resolution, so every cell is a half block and no fitting is needed.

use crate::logos::{Art, Cell};

pub struct Mark {
    pub id: &'static str,
    pub rgb: (u8, u8, u8),
    pub art: Art,
}

pub fn find(id: &str) -> Option<&'static Mark> {
    MARKS.iter().find(|m| m.id == id)
}

