pub const MARKS: &[Mark] = &[
    Mark { id: "netjail", rgb: (236, 160, 92),
          art: Art { cols: 30, rows: 13, cells: &NETJAIL_MARK } },
    Mark { id: "watch-party", rgb: (253, 74, 90),
          art: Art { cols: 30, rows: 15, cells: &WATCH_PARTY_MARK } },
    Mark { id: "logify", rgb: (120, 200, 226),
          art: Art { cols: 30, rows: 13, cells: &LOGIFY_MARK } },
    Mark { id: "clip", rgb: (110, 200, 180),
          art: Art { cols: 30, rows: 13, cells: &CLIP_MARK } },
    Mark { id: "noter", rgb: (214, 158, 178),
          art: Art { cols: 30, rows: 13, cells: &NOTER_MARK } },
    Mark { id: "gitswitch", rgb: (222, 190, 148),
          art: Art { cols: 30, rows: 13, cells: &GITSWITCH_MARK } },
    Mark { id: "vcs", rgb: (150, 176, 206),
          art: Art { cols: 30, rows: 13, cells: &VCS_MARK } },
    Mark { id: "stylized-maps", rgb: (140, 196, 148),
          art: Art { cols: 30, rows: 13, cells: &STYLIZED_MAPS_MARK } },
    Mark { id: "termap", rgb: (176, 208, 232),
          art: Art { cols: 30, rows: 13, cells: &TERMAP_MARK } },
];

/// Every project mark, side by side. Same purpose as the tool contact sheet:
/// these are composed by a script that cannot see a terminal.
pub fn sheet() -> String {
    const BG: (u8, u8, u8) = (6, 7, 10);
    let blend = |c: (u8, u8, u8), a: u8| {
        let a = a as f32 / 255.0;
        (
            (BG.0 as f32 + (c.0 as f32 - BG.0 as f32) * a) as u8,
            (BG.1 as f32 + (c.1 as f32 - BG.1 as f32) * a) as u8,
            (BG.2 as f32 + (c.2 as f32 - BG.2 as f32) * a) as u8,
        )
    };
    let mut out = String::new();
    for row in MARKS.chunks(3) {
        let h = row.iter().map(|m| m.art.rows).max().unwrap_or(0);
        for r in 0..h {
            for m in row {
                let a = &m.art;
                for c in 0..a.cols {
                    if r >= a.rows {
                        out.push(' ');
                        continue;
                    }
                    let (ch, f, b) = a.cells[(r * a.cols + c) as usize];
                    if f == 0 && b == 0 {
                        out.push_str("\x1b[0m ");
                        continue;
                    }
                    let (fr, fg, fb) = blend(m.rgb, f);
                    let (br, bg, bb) = blend(m.rgb, b);
                    out.push_str(&format!(
                        "\x1b[38;2;{fr};{fg};{fb}m\x1b[48;2;{br};{bg};{bb}m{ch}"
                    ));
                }
                out.push_str("\x1b[0m");
                out.push_str(&" ".repeat(40usize.saturating_sub(a.cols as usize)));
            }
            out.push('\n');
        }
        for m in row {
            out.push_str(&format!("\x1b[38;2;150;155;165m{:<40}\x1b[0m", m.id));
        }
        out.push_str("\n\n");
    }
    out
}
